  { id: "2", name: "Đà Nẵng" },
  { id: "3", name: "TP.HCM" },
];

export default function App() {
  return (
    <FlatList
      data={DATA}
      keyExtractor={(item) => item.id}
      renderItem={({ item }) => (
        <View style={styles.row}>
          <Text>{item.name}</Text>
        </View>
      )}
    />
  );
}

const styles = StyleSheet.create({
  row: { padding: 14, borderBottomWidth: 1, borderColor: "#ddd" },
});

