import { useState } from "react";
import { View, Text, Pressable } from "react-native";

export default function App() {
  const [screen, setScreen] = useState("home");
  if (screen === "detail") {
    return (
      <View>
        <Text testID="title">Detail</Text>
        <Pressable testID="back" onPress={() => setScreen("home")}>
          <Text>Quay lại</Text>
        </Pressable>
      </View>
    );
  }
  return (
    <View>
      <Pressable testID="go" onPress={() => setScreen("detail")}>
        <Text>Đi tới chi tiết</Text>
      </Pressable>
    </View>
  );
}
